nt)!important} #ps-root .btn:hover:not(:disabled){filter:brightness(1.16)} #ps-root .btn:disabled{opacity:.5} #ps-root button:focus-visible,#ps-root a:focus-visible,#ps-root summary:focus-visible{outline:2px solid var(--ps-accent);outline-offset:3px}\n#ps-root .table{color:var(--ps-fg)!important;background:transparent!important;font-size:12px} #ps-root .table th{color:var(--ps-accent)!important;background:#14231b!important} #ps-root .table td,#ps-root .table th{border-color:var(--ps-line)!important;overflow-wrap:anywhere;vertical-align:top} #ps-root .table-striped>tbody>tr:nth-of-type(odd){background:#142019!important} #ps-root .table-striped>tbody>tr:nth-of-type(even){background:#0e1713!important} #ps-root .table-responsive{border-color:var(--ps-line)!important} #ps-root .callout{color:var(--ps-fg)!important;background:#302515!important;border-left-color:#ffbf69!important}\n#ps-root .ps-hero{border:1px solid #38684c;border-left:4px solid var(--ps-accent);padding:22px;margin-bottom:18px;border-radius:5px;background:linear-gradient(115deg,#12281c,#0b1510)} #ps-root .ps-kicker{font-size:11px;letter-spacing:.18em;color:var(--ps-accent);font-weight:700} #ps-root .ps-hero h2{font-family:inherit;color:#ebfff3;font-weight:700;font-size:clamp(22px,3vw,34px);margin:8px 0} #ps-root .ps-hero p{color:var(--ps-muted)} #ps-root .ps-hero-meta{display:flex;flex-wrap:wrap;gap:8px;margin-top:16px} #ps-root .ps-hero-meta span{font-size:11px;border:1px solid #365642;padding:4px 8px;color:var(--ps-accent);border-radius:3px}\n#ps-root .ps-actions{display:flex;flex-wrap:wrap;gap:8px;margin:8px 0 15px} #ps-root .ps-status-line{border-left:2px solid var(--ps-accent);padding:8px 12px;background:#0a130e;color:var(--ps-accent);overflow-wrap:anywhere} #ps-root .ps-report{white-space:pre-wrap;overflow-wrap:anywhere;color:#d9f2e1!important;background:#080e0c!important;border:1px solid var(--ps-line);border-radius:4px;padding:20px;min-height:180px;font-family:inherit;font-size:14px;line-height:1.8