def replace_once(s, old, new):
    if s.count(old)!=1: raise RuntimeError('Unexpected PiShield template; no files changed: '+old[:80])
    return s.replace(old,new,1)

def patch(p,j):
    if not p.startswith('<!-- PiShield extension v0.3 -->') or not j.startswith('// PiShield extension v0.3\n'):
        raise RuntimeError('Expected PiShield v0.3. No files changed.')
    p=replace_once(p,'<!-- PiShield extension v0.3 -->','<!-- PiShield extension v0.3.2 -->')
    p=replace_once(p,'<strong>PiShield v0.3</strong>','<strong>PiShield v0.3.2</strong>')
    a=p.index('<div class="row" id="ai">'); b=p.index('\n</div>\n<script',a)
    p=p[:a]+new_ai_html+p[b:]
    p=replace_once(p,'<div id="ps-root">',theme_css+'\n<div id="ps-root">')
    j=replace_once(j,'// PiShield extension v0.3\n','// PiShield extension v0.3.2\n')
    a=j.index('  function prepareAI()');b=j.index('  function initV3()',a)
    j=j[:a]+new_ai_js+j[b:]
    j=replace_once(j,'el("ps-ai-prepare").addEventListener("click",prepareAI);','el("ps-ai-save-report").addEventListener("click",downloadAIAnswer);el("ps-ai-reload-models").addEventListener("click",loadAIModels);el("ps-ai-model").addEventListener("change",()=>{save("ai-model",el("ps-ai-model").value);aiControls();});el("ps-ai-window").addEventListener("change",()=>{aiReport=null;clearAIData();delete el("ps-ai-output").dataset.complete;el("ps-ai-prompt").value="";el("ps-ai-metrics").replaceChildren();text("ps-ai-data-status","History period changed; load or analyze again.");text("ps-ai-output","No report for the selected period yet.");aiControls();});el("ps-ai-prepare").addEventListener("click",prepareAI);')
    old='if(location.hash==="#profiles")reloadProfiles();}'
    if j.count(old)!=2: raise RuntimeError('Unexpected initialization; no files changed.')
    j=j.replace(old,'if(location.hash==="#profiles")reloadProfiles();if(location.hash==="#ai")loadAIModels();}')
    return p,j

