header=root/'scripts/lua/header.lp'
index=root/'index.lp'
css=root/'style/pishield-terminal.css'
hstart='<!-- PISHIELD THEME BEGIN -->'; hend='<!-- PISHIELD THEME END -->'
bstart='<!-- PISHIELD HOME BEGIN -->'; bend='<!-- PISHIELD HOME END -->'
cssmarker='/* PiShield global terminal theme'

def strip_block(value,a,b):
    if value.count(a)!=value.count(b) or value.count(a)>1: raise RuntimeError('Malformed theme markers; no files changed.')
    return re.sub(re.escape(a)+r'.*?'+re.escape(b)+r'\n?', '',value,flags=re.S)

def atomic(path,value):
    st=path.stat() if path.exists() else None
    fd,tmp=tempfile.mkstemp(prefix='.pishield-',dir=path.parent)
    try:
        with os.fdopen(fd,'w') as f: f.write(value)
        os.chmod(tmp,st.st_mode & 0o777 if st else 0o644)
        if st: os.chown(tmp,st.st_uid,st.st_gid)
        os.replace(tmp,path)
    finally:
        if os.path.exists(tmp): os.unlink(tmp)

files=[header,index,page,js,css]
for f in files:
    if f.is_symlink(): raise RuntimeError('Unexpected symlink: '+str(f))
    if f!=css and not f.is_file(): raise RuntimeError('Missing file: '+str(f))
original={f:f.read_text() if f.exists() else None for f in files}
if original[css] is not None and not original[css].startswith(cssmarker): raise RuntimeError('Theme CSS filename conflict; no files changed.')
h=strip_block(original[header],hstart,hend)
i=strip_block(original[index],bstart,bend)
if sys.argv[1]=='remove-theme':
    updates={header:h,index:i,css:None}
else:
    p,j=original[page],original[js]
    if p.startswith('<!-- PiShield extension v0.4 -->') and j.startswith('// PiShield extension v0.4\n'):
        pnew,jnew=p,j
    elif p.startswith('<!-- PiShield extension v0.3.2 -->') and j.startswith('// PiShield extension v0.3.2\n'):
        pnew,jnew=p,j
    else:
        pnew,jnew=patch(p,j)
    pnew=pnew.replace('PiShield extension v0.3.2','PiShield extension v0.4').replace('PiShield v0.3.2','PiShield v0.4')
    jnew=jnew.replace('PiShield extension v0.3.2','PiShield extension v0.4')
    # Install a shared stylesheet after the built-in theme, for native admin and login pages alike.
    anchor='    <noscript><link rel="stylesheet"'
    if h.count(anchor)!=1: raise RuntimeError('Unknown native header layout; no files changed.')
    h=h.replace(anchor,hstart+"\n<link rel=\"stylesheet\" href=\"<?=pihole.fileversion('style/pishield-terminal.css')?>\">\n"+hend+"\n"+anchor,1)
    # Insert the banner into the native authenticated homepage, outside of the existing statistic rows.
    anchor="mg.include('scripts/lua/header_authenticated.lp','r')"
    if i.count(anchor)!=1: raise RuntimeError('Unknown native homepage layout; no files changed.')
    pos=i.index('?>',i.index(anchor))+2
    banner= bstart+"\n"+ '<section class="ps-native-banner"><div class="ps-native-kicker">PISHIELD // NETWORK DEFENSE CONSOLE</div><h2>Network command center</h2><p>Pi-hole DNS telemetry · Live network monitoring · Local AI intelligence</p><a class="btn btn-primary" href="<?=webhome?>pishield#ai">AI ANALYST</a><a class="btn btn-default" href="<?=webhome?>pishield#overview">SECURITY OVERVIEW</a><a class="btn btn-default" href="<?=webhome?>pishield-system">NETWORK HEALTH</a></section>' +"\n"+bend+"\n"
    i=i[:pos]+"\n"+banner+i[pos:]
    updates={header:h,index:i,page:pnew,js:jnew,css:global_css}
backup_root=Path('/var/backups/pishield')
backup_root.mkdir(parents=True,exist_ok=True,mode=0o700)
backup=Path(tempfile.mkdtemp(prefix='terminal-v04-'+time.strftime('%Y%m%d-%H%M%S')+'-',dir=backup_root))
for f in updates:
    if f.exists(): shutil.copy2(f,backup/f.name)
try:
    for f,value in updates.items():
        if value is None: f.unlink(missing_ok=True)
        else: atomic(f,value)
except BaseException:
    for f in updates:
        if original[f] is None: f.unlink(missing_ok=True)
        else: atomic(f,original[f])
    raise
print('PiShield v0.4 terminal theme and AI upgrade installed.' if sys.argv[1]=='install' else 'Native theme restored. AI upgrade retained.')
print('Backup:',backup)
print('No DNS settings, services, blocklists or security headers changed.')
